payloads=[bytes.fromhex(x) for x in ['00','4e71','4e75','303c1234','203c12345678','a900','a901','69ff','ea00','8d3412']]
for fb in range(0,32):
    for idx,p in enumerate(payloads):
        Path(f'br_{fb:02x}_{idx}.bin').write_bytes(bytes([fb])+p)
